import re

s=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
L=len(s)
comp=str.maketrans('ACGT','TGCA')
rc=s.translate(comp)[::-1]

stops={'TAA','TAG','TGA'}
starts={'ATG','GTG','TTG'}

def orfs(seq):
    out=[]
    for frame in range(3):
        i=frame
        while i+3<=len(seq):
            codon=seq[i:i+3]
            if codon in stops:
                # walk backwards to find start
                j=i
                while j-3>=frame:
                    j-=3
                    c=seq[j:j+3]
                    if c in stops:
                        break
                # collect starts between j and i
                k=j
                while k<=i-3:
                    if seq[k:k+3] in starts:
                        out.append((k, i, frame, seq[k:i+3]))
                    k+=3
                i+=3
            else:
                i+=3
    return out

code = {}
bases='TCAG'
aas='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
i=0
for b1 in bases:
    for b2 in bases:
        for b3 in bases:
            code[b1+b2+b3]=aas[i]; i+=1

def prot(nt): return ''.join(code.get(nt[i:i+3],'X') for i in range(0,len(nt)-2,3))

print("=== sense strand ORFs (any start, >=100 aa) ===")
res=[]
for st,en,fr,nt in orfs(s):
    if (en-st)//3 >= 100:
        res.append(('+',st+1,en+3,(en-st)//3,prot(nt)))
for st,en,fr,nt in orfs(rc):
    if (en-st)//3 >= 100:
        m=len(rc)-(en+3)
        res.append(('-',st+1,len(rc)-en,(en-st)//3,prot(nt)))
res.sort(key=lambda x:-x[3])
